style.css:
/* Change all link colors */
a {
    color: #2E3B28 !important; /* Default link color */
    text-decoration: none !important; /* Optional: remove underline */
}

/* Hover effect */
a:hover {
    color: #2E3B28 !important; /* Color on hover */
    text-decoration: underline !important; /* Optional: add underline on hover */
}

/* Visited links */
a:visited {
    color: #5E7950 !important; /* Change color of visited links */
}
